import axios from "axios";
import { config } from "../config";
import { getMusicPoweredAPI } from "./quivers-api";

// quivers-api.ts is generated by Orval (yarn api-generate). Don't edit it;
// configure requests here instead.
export const http = axios.create({
  baseURL: config.apiBaseUrl,
  timeout: config.requestTimeoutMs,
});

export const api = getMusicPoweredAPI(http);

export type {
  About,
  BandMember,
  CreateOrderDto,
  Merch,
  MerchVariation,
  Playlist,
  SiteSettings,
} from "./quivers-api";

/** A readable message from an API or network error. */
export const errorMessage = (error: unknown, fallback = "Please try again."): string => {
  if (axios.isAxiosError(error)) {
    const data = error.response?.data as { message?: unknown; Message?: unknown } | undefined;
    const message = data?.Message ?? data?.message;
    if (typeof message === "string" && message) return message;
    if (!error.response) return "We couldn't reach our server. Check your connection and try again.";
  }
  return fallback;
};
